 * @param <K> the type of keys maintained by this map
 * @param <V> the type of mapped values
 */
public final class OpenAddressingHashMap<K, V> implements Iterable<OpenAddressingHashMap.Entry<K, V>> {

    /** An immutable, read-only view of a single key/value mapping. */
    public interface Entry<K, V> {
        /** Returns this mapping's key. */
        K getKey();

        /** Returns this mapping's value (may be {@code null}). */
        V getValue();
    }

