                }
            }
            return null;
        }

        @Override
        public boolean hasNext() {
            return nextSlot != null;
        }

        @Override
        public Entry<K, V> next() {
            return nextSlot();
        }

        Slot<K, V> nextSlot() {
            if (map.modCount != expectedModCount) {
                throw new ConcurrentModificationException();
            }
            if (nextSlot == null) {
                throw new NoSuchElementException();
            }
            Slot<K, V> current = nextSlot;
            nextSlot = advance();
